import React, { useState, useEffect, useRef } from "react";
import { Link, NavLink, useLocation, useSearchParams } from "react-router-dom";

// Импорт логотипов (пути подправлены под структуру src)
import plLogo from "../../assets/leagues/premier-league.png";
import blLogo from "../../assets/leagues/bundesliga.png";
import saLogo from "../../assets/leagues/serie-a.png";
import pdLogo from "../../assets/leagues/la-liga.png";
import flLogo from "../../assets/leagues/ligue-1.png";

const leagues = [
  { code: null, name: "ВСЕ", logo: null },
  { code: "Premier_League", name: "Premier League", logo: plLogo },
  { code: "La_Liga", name: "La Liga", logo: pdLogo },
  { code: "Serie_A", name: "Serie A", logo: saLogo },
  { code: "Bundesliga", name: "Bundesliga", logo: blLogo },
  { code: "Ligue_1", name: "Ligue 1", logo: flLogo },
];

function Header() {
  const [isLeagueOpen, setIsLeagueOpen] = useState(false);
  const [searchParams] = useSearchParams();
  const currentLeagueCode = searchParams.get("league");
  const location = useLocation();
  const dropdownRef = useRef(null);

  // Закрытие меню при клике вне его области или при смене страницы
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsLeagueOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      setIsLeagueOpen(false);
    };
  }, [location]);

  return (
    <header className="bg-gray-950 border-b border-gray-900 sticky top-0 z-[100] w-full">
      <div className="container mx-auto px-4 h-20 flex items-center justify-between gap-4">
        {/* ЛЕВАЯ ЧАСТЬ: Логотип + Выпадающий список лиг */}
        <div
          className="flex items-center gap-4 flex-shrink-0"
          ref={dropdownRef}
        >
          <Link to="/" className="hidden md:block">
            <span className="text-xl lg:text-2xl font-black tracking-tighter text-gradient-neuro-title">
              NeuroPredict
            </span>
          </Link>

          {/* Кнопка открытия Лиг (Квадратик) */}
          <button
            onClick={() => setIsLeagueOpen(!isLeagueOpen)}
            className={`w-12 h-12 rounded-xl border-2 flex items-center justify-center transition-all ${
              isLeagueOpen || currentLeagueCode
                ? "bg-red-600 border-red-600 shadow-[0_0_15px_rgba(220,38,38,0.4)]"
                : "bg-gray-900 border-gray-800 text-gray-500"
            }`}
          >
            <svg
              className="w-6 h-6 text-white"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M4 6h16M4 12h16m-7 6h7"
              />
            </svg>
          </button>

          {/* ВЫПАДАЮЩАЯ СЕТКА (Стиль Sidebar) */}
          {isLeagueOpen && (
            <div className="absolute top-full left-4 mt-2 w-[280px] sm:w-[350px] bg-gray-950 border border-gray-800 rounded-2xl shadow-2xl p-4 animate-in fade-in slide-in-from-top-2 duration-200">
              <div className="grid grid-cols-3 gap-3">
                {leagues.map((league) => {
                  const isActive =
                    currentLeagueCode === league.code ||
                    (!currentLeagueCode && league.code === null);
                  return (
                    <NavLink
                      key={league.code || "all"}
                      to={league.code ? `/?league=${league.code}` : "/"}
                      className="flex flex-col items-center group"
                    >
                      <div
                        className={`w-16 h-16 rounded-xl border-2 flex items-center justify-center transition-all ${
                          isActive
                            ? "bg-red-600 border-red-600 shadow-lg"
                            : "bg-gray-900 border-gray-800 group-hover:border-red-600"
                        }`}
                      >
                        {league.logo ? (
                          <img
                            src={league.logo}
                            alt=""
                            className="w-10 h-10 object-contain"
                          />
                        ) : (
                          <span className="text-xs font-black text-yellow-500">
                            ALL
                          </span>
                        )}
                      </div>
                      <span
                        className={`text-[10px] mt-1 font-bold uppercase tracking-tighter text-center ${isActive ? "text-red-500" : "text-gray-500"}`}
                      >
                        {league.name.split(" ")[0]}
                      </span>
                    </NavLink>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* ЦЕНТРАЛЬНАЯ ЧАСТЬ: Поиск */}
        <div className="flex-grow max-w-xl relative">
          <input
            type="text"
            placeholder="Поиск матча..."
            className="w-full bg-gray-900 border border-gray-800 rounded-2xl py-2.5 px-5 text-sm text-gray-300 focus:outline-none focus:ring-2 focus:ring-red-600/50 transition-all"
          />
          <div className="absolute right-4 top-3 text-gray-600">
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
              />
            </svg>
          </div>
        </div>

        {/* ПРАВАЯ ЧАСТЬ: Кнопка Сравнения */}
        <div className="flex-shrink-0">
          <button className="flex items-center gap-2 bg-gray-900 border border-gray-800 p-2.5 rounded-xl hover:border-red-600 transition-all group">
            <svg
              className="w-5 h-5 text-gray-600 group-hover:text-red-600"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="橫9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"
              />
            </svg>
            <span className="hidden xl:block text-[10px] font-black uppercase text-gray-500 group-hover:text-red-600 tracking-widest">
              H2H Compare
            </span>
          </button>
        </div>
      </div>
    </header>
  );
}

export default Header;
